const raw = ($json.stdout || '').trim();
if (!raw) {
  throw new Error('Prepare command returned empty stdout');
}
const data = JSON.parse(raw);
if (!data.ok) {
  throw new Error(`Prepare failed: ${data.error || data.stderr || raw}`);
}
return [{ json: data }];

return [{
  json: {
    ok: true,
    stage: 'review',
    message: 'Bundle prepared. Review the generated package, then rerun with autoPublish=true and existingPackageDir set to this package.',
    packageDir: $json.packageDir,
    title: $json.bundle?.title || '',
    summary: $json.bundle?.summary || '',
    cover: $json.bundle?.cover || '',
    files: $json.bundle?.files || {},
    images: $json.bundle?.images || []
  }
}];

parameters.command:
={{ (() => {
  const cfg = $node["Workflow Config"].json;
  const q = (value) => JSON.stringify(String(value));
  const workspaceRoot = cfg.workspaceRoot || '/workspace/agent-skills';
  const parts = [
    'python3',
    q(`${workspaceRoot}/scripts/n8n_hotspot_bridge.py`),
    'publish',
    '--package-dir',
    q($json.packageDir)
  ];

  if (cfg.platforms) parts.push('--platforms', q(cfg.platforms));
  if (cfg.withTencent) parts.push('--with-tencent');
  if (cfg.titleOverride) parts.push('--title', q(cfg.titleOverride));
  if (cfg.coverOverride) parts.push('--cover', q(cfg.coverOverride));
  if (cfg.wechatMethod) parts.push('--wechat-method', q(cfg.wechatMethod));
  if (cfg.wechatAuthor) parts.push('--wechat-author', q(cfg.wechatAuthor));
  if (cfg.wechatSummary) parts.push('--wechat-summary', q(cfg.wechatSummary));
  if (cfg.wechatProfile) parts.push('--wechat-profile', q(cfg.wechatProfile));
  if (cfg.xhsMode) parts.push('--xhs-mode', q(cfg.xhsMode));
  if (cfg.xhsTemplate) parts.push('--xhs-template', q(cfg.xhsTemplate));
  if (cfg.xhsAccount) parts.push('--xhs-account', q(cfg.xhsAccount));
  if (cfg.headlessBrowser === false) parts.push('--no-headless-browser');
  else parts.push('--headless-browser');
  if (cfg.tencentHeadless === false) parts.push('--no-tencent-headless');
  else parts.push('--tencent-headless');
  if (cfg.dryRun) parts.push('--dry-run');

  return parts.join(' ');
})() }}

